{
  \"status\": \"frozen\",
  \"interface\": {
    \"module\": \"TopModule\",
    \"inputs\": {\"in\": \"[99:0]\"},
    \"outputs\": {\"out_both\": \"[99:0]\", \"out_any\": \"[99:0]\", \"out_different\": \"[99:0]\"},
    \"extra_ports\": false
  },
  \"semantics\": {
    \"kind\": \"combinational; outputs follow input without clock or latency\",
    \"evidence\": \"Original problem defines each output directly from the input vector and specifies no clock, reset, or state.\",
    \"out_both\": \"For i=0..98, in[i] AND in[i+1]; bit 99 is constant zero.\",
    \"out_any\": \"For i=1..99, in[i] OR in[i-1]; bit 0 is constant zero.\",
    \"out_different\": \"For i=0..98, in[i] XOR in[i+1]; bit 99 is in[99] XOR in[0].\",
    \"reset_initialization\": \"No reset or stored initialization is specified or required; no registers.\"
  },
  \"numeric\": {
    \"width\": 100,
    \"index_direction\": \"Left neighbour is the next larger index; right neighbour is the next smaller index.\",
    \"operations\": \"One-bit Boolean gates, with no arithmetic or signedness dependence.\"
  },
  \"verification\": {
    \"oracle\": \"Per-bit loop based on the original neighbour descriptions, independent of DUT concatenations.\",
    \"sampling\": \"Drive vector then allow one simulation time unit for combinational settling.\",
    \"cases\": \"All zeros, all ones, alternating patterns, each single set and cleared bit, exhaustive local adjacent pair combinations, deterministic random vectors.\",
    \"failure\": \""'$fatal for any output mismatch; bounded timeout; PASS only at completion."
  },
  "specification_ambiguities": [
    "Original problem does not specify X/Z behavior; ordinary bitwise gate propagation is used, with supplemental four-state checks but no claim of a separate required X/Z contract."
  ]
}
EOF
python3 validate_contract.py'

